-- D1 verification counters are updated in the same transaction as source rows.
-- The original complete SELECT remains a daily independent reconciliation.
CREATE TABLE IF NOT EXISTS d1_verification_totals(metric TEXT PRIMARY KEY,value INTEGER NOT NULL CHECK(value>=0));
CREATE TABLE IF NOT EXISTS d1_daily_verification(id TEXT PRIMARY KEY,verified_date TEXT NOT NULL,version TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS verification_app_match ON app_matches(json_extract(payload,'$.circuit'),json_extract(payload,'$.matchId'));
INSERT INTO d1_verification_totals(metric,value) SELECT 'players',COUNT(*) FROM players WHERE 1 ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'entries',COUNT(*) FROM entries WHERE 1 ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'observedPlayers',COUNT(*) FROM observed_players WHERE 1 ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'observedFitp',COUNT(*) FROM observed_players WHERE circuit='fitp' ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'observedTe',COUNT(*) FROM observed_players WHERE circuit='tennis-europe' ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'observedItf',COUNT(*) FROM observed_players WHERE circuit='itf' ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'teOopTournaments',COUNT(*) FROM tournaments WHERE id LIKE 'te-oop:%' ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'teMatches',COUNT(*) FROM matches WHERE circuit='tennis-europe' ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'teSchedules',COUNT(*) FROM schedules WHERE circuit='tennis-europe' ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'teResults',COUNT(*) FROM results WHERE circuit='tennis-europe' ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'tePlayers',COUNT(*) FROM tennis_europe_players WHERE 1 ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'teParticipants',COUNT(*) FROM match_participants WHERE 1 ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'candidateRelations',COUNT(*) FROM app_match_candidates WHERE 1 ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'candidateUniqueMatches',COUNT(DISTINCT match_id) FROM app_match_candidates WHERE match_id IS NOT NULL ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'appMatches',COUNT(*) FROM app_matches WHERE json_extract(payload,'$.circuit')='tennis-europe' ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'appUniqueMatches',COUNT(DISTINCT json_extract(payload,'$.matchId')) FROM app_matches WHERE json_extract(payload,'$.circuit')='tennis-europe' AND json_extract(payload,'$.matchId') IS NOT NULL ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'appInvalid',COUNT(*) FROM app_matches WHERE json_extract(payload,'$.circuit')='tennis-europe' AND (COALESCE(json_extract(payload,'$.playerId'),'')='' OR COALESCE(json_extract(payload,'$.matchId'),'')='' OR COALESCE(json_extract(payload,'$.date'),'')='' OR COALESCE(json_extract(payload,'$.tournamentName'),'')='' OR COALESCE(json_extract(payload,'$.opponent'),'')='' OR COALESCE(json_extract(payload,'$.round'),'')='' OR (json_extract(payload,'$.status')='completed' AND COALESCE(json_extract(payload,'$.result'),'')='')) ON CONFLICT(metric) DO NOTHING;
INSERT INTO d1_verification_totals(metric,value) SELECT 'appMissingCourtMatchNumbers',COUNT(*) FROM app_matches WHERE json_extract(payload,'$.circuit')='tennis-europe' AND COALESCE(json_extract(payload,'$.court'),'')<>'' AND json_extract(payload,'$.sourceUrl') LIKE '%/matches/%' AND COALESCE(CAST(json_extract(payload,'$.courtMatchNumber') AS INTEGER),0)<=0 ON CONFLICT(metric) DO NOTHING;
CREATE TRIGGER IF NOT EXISTS verification_app_match_candidates_insert AFTER INSERT ON app_match_candidates BEGIN
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (1) THEN 1 ELSE 0 END) WHERE metric='candidateRelations' AND (CASE WHEN (1) THEN 1 ELSE 0 END)<>0;
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (NEW.match_id IS NOT NULL) AND (SELECT COUNT(*) FROM (SELECT 1 FROM app_match_candidates WHERE (match_id IS NOT NULL) AND match_id IS NEW.match_id LIMIT 2))=1 THEN 1 ELSE 0 END) WHERE metric='candidateUniqueMatches' AND (CASE WHEN (NEW.match_id IS NOT NULL) AND (SELECT COUNT(*) FROM (SELECT 1 FROM app_match_candidates WHERE (match_id IS NOT NULL) AND match_id IS NEW.match_id LIMIT 2))=1 THEN 1 ELSE 0 END)<>0;
END;
CREATE TRIGGER IF NOT EXISTS verification_app_match_candidates_delete AFTER DELETE ON app_match_candidates BEGIN
 UPDATE d1_verification_totals SET value=value+(-(CASE WHEN (1) THEN 1 ELSE 0 END)) WHERE metric='candidateRelations' AND (-(CASE WHEN (1) THEN 1 ELSE 0 END))<>0;
 UPDATE d1_verification_totals SET value=value+(-(CASE WHEN (OLD.match_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM app_match_candidates WHERE (match_id IS NOT NULL) AND match_id IS OLD.match_id) THEN 1 ELSE 0 END)) WHERE metric='candidateUniqueMatches' AND (-(CASE WHEN (OLD.match_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM app_match_candidates WHERE (match_id IS NOT NULL) AND match_id IS OLD.match_id) THEN 1 ELSE 0 END))<>0;
END;
CREATE TRIGGER IF NOT EXISTS verification_app_match_candidates_update AFTER UPDATE ON app_match_candidates BEGIN
 UPDATE d1_verification_totals SET value=value+((CASE WHEN (1) THEN 1 ELSE 0 END)-(CASE WHEN (1) THEN 1 ELSE 0 END)) WHERE metric='candidateRelations' AND ((CASE WHEN (1) THEN 1 ELSE 0 END)-(CASE WHEN (1) THEN 1 ELSE 0 END))<>0;
 UPDATE d1_verification_totals SET value=value+((CASE WHEN NOT ((OLD.match_id IS NOT NULL) AND (NEW.match_id IS NOT NULL) AND OLD.match_id IS NEW.match_id) THEN (CASE WHEN (NEW.match_id IS NOT NULL) AND (SELECT COUNT(*) FROM (SELECT 1 FROM app_match_candidates WHERE (match_id IS NOT NULL) AND match_id IS NEW.match_id LIMIT 2))=1 THEN 1 ELSE 0 END) ELSE 0 END)-(CASE WHEN NOT ((OLD.match_id IS NOT NULL) AND (NEW.match_id IS NOT NULL) AND OLD.match_id IS NEW.match_id) THEN (CASE WHEN (OLD.match_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM app_match_candidates WHERE (match_id IS NOT NULL) AND match_id IS OLD.match_id) THEN 1 ELSE 0 END) ELSE 0 END)) WHERE metric='candidateUniqueMatches' AND ((CASE WHEN NOT ((OLD.match_id IS NOT NULL) AND (NEW.match_id IS NOT NULL) AND OLD.match_id IS NEW.match_id) THEN (CASE WHEN (NEW.match_id IS NOT NULL) AND (SELECT COUNT(*) FROM (SELECT 1 FROM app_match_candidates WHERE (match_id IS NOT NULL) AND match_id IS NEW.match_id LIMIT 2))=1 THEN 1 ELSE 0 END) ELSE 0 END)-(CASE WHEN NOT ((OLD.match_id IS NOT NULL) AND (NEW.match_id IS NOT NULL) AND OLD.match_id IS NEW.match_id) THEN (CASE WHEN (OLD.match_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM app_match_candidates WHERE (match_id IS NOT NULL) AND match_id IS OLD.match_id) THEN 1 ELSE 0 END) ELSE 0 END))<>0;
END;
CREATE TRIGGER IF NOT EXISTS verification_app_matches_insert AFTER INSERT ON app_matches BEGIN
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (json_extract(NEW.payload,'$.circuit')='tennis-europe') THEN 1 ELSE 0 END) WHERE metric='appMatches' AND (CASE WHEN (json_extract(NEW.payload,'$.circuit')='tennis-europe') THEN 1 ELSE 0 END)<>0;
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (json_extract(NEW.payload,'$.circuit')='tennis-europe' AND json_extract(NEW.payload,'$.matchId') IS NOT NULL) AND (SELECT COUNT(*) FROM (SELECT 1 FROM app_matches WHERE (json_extract(payload,'$.circuit')='tennis-europe' AND json_extract(payload,'$.matchId') IS NOT NULL) AND json_extract(payload,'$.matchId') IS json_extract(NEW.payload,'$.matchId') LIMIT 2))=1 THEN 1 ELSE 0 END) WHERE metric='appUniqueMatches' AND (CASE WHEN (json_extract(NEW.payload,'$.circuit')='tennis-europe' AND json_extract(NEW.payload,'$.matchId') IS NOT NULL) AND (SELECT COUNT(*) FROM (SELECT 1 FROM app_matches WHERE (json_extract(payload,'$.circuit')='tennis-europe' AND json_extract(payload,'$.matchId') IS NOT NULL) AND json_extract(payload,'$.matchId') IS json_extract(NEW.payload,'$.matchId') LIMIT 2))=1 THEN 1 ELSE 0 END)<>0;
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (json_extract(NEW.payload,'$.circuit')='tennis-europe' AND (COALESCE(json_extract(NEW.payload,'$.playerId'),'')='' OR COALESCE(json_extract(NEW.payload,'$.matchId'),'')='' OR COALESCE(json_extract(NEW.payload,'$.date'),'')='' OR COALESCE(json_extract(NEW.payload,'$.tournamentName'),'')='' OR COALESCE(json_extract(NEW.payload,'$.opponent'),'')='' OR COALESCE(json_extract(NEW.payload,'$.round'),'')='' OR (json_extract(NEW.payload,'$.status')='completed' AND COALESCE(json_extract(NEW.payload,'$.result'),'')=''))) THEN 1 ELSE 0 END) WHERE metric='appInvalid' AND (CASE WHEN (json_extract(NEW.payload,'$.circuit')='tennis-europe' AND (COALESCE(json_extract(NEW.payload,'$.playerId'),'')='' OR COALESCE(json_extract(NEW.payload,'$.matchId'),'')='' OR COALESCE(json_extract(NEW.payload,'$.date'),'')='' OR COALESCE(json_extract(NEW.payload,'$.tournamentName'),'')='' OR COALESCE(json_extract(NEW.payload,'$.opponent'),'')='' OR COALESCE(json_extract(NEW.payload,'$.round'),'')='' OR (json_extract(NEW.payload,'$.status')='completed' AND COALESCE(json_extract(NEW.payload,'$.result'),'')=''))) THEN 1 ELSE 0 END)<>0;
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (json_extract(NEW.payload,'$.circuit')='tennis-europe' AND COALESCE(json_extract(NEW.payload,'$.court'),'')<>'' AND json_extract(NEW.payload,'$.sourceUrl') LIKE '%/matches/%' AND COALESCE(CAST(json_extract(NEW.payload,'$.courtMatchNumber') AS INTEGER),0)<=0) THEN 1 ELSE 0 END) WHERE metric='appMissingCourtMatchNumbers' AND (CASE WHEN (json_extract(NEW.payload,'$.circuit')='tennis-europe' AND COALESCE(json_extract(NEW.payload,'$.court'),'')<>'' AND json_extract(NEW.payload,'$.sourceUrl') LIKE '%/matches/%' AND COALESCE(CAST(json_extract(NEW.payload,'$.courtMatchNumber') AS INTEGER),0)<=0) THEN 1 ELSE 0 END)<>0;
END;
