 UPDATE d1_verification_totals SET value=value+(-(CASE WHEN (json_extract(OLD.payload,'$.circuit')='tennis-europe') THEN 1 ELSE 0 END)) WHERE metric='appMatches' AND (-(CASE WHEN (json_extract(OLD.payload,'$.circuit')='tennis-europe') THEN 1 ELSE 0 END))<>0;
 UPDATE d1_verification_totals SET value=value+(-(CASE WHEN (json_extract(OLD.payload,'$.circuit')='tennis-europe' AND json_extract(OLD.payload,'$.matchId') IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM app_matches WHERE (json_extract(payload,'$.circuit')='tennis-europe' AND json_extract(payload,'$.matchId') IS NOT NULL) AND json_extract(payload,'$.matchId') IS json_extract(OLD.payload,'$.matchId')) THEN 1 ELSE 0 END)) WHERE metric='appUniqueMatches' AND (-(CASE WHEN (json_extract(OLD.payload,'$.circuit')='tennis-europe' AND json_extract(OLD.payload,'$.matchId') IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM app_matches WHERE (json_extract(payload,'$.circuit')='tennis-europe' AND json_extract(payload,'$.matchId') IS NOT NULL) AND json_extract(payload,'$.matchId') IS json_extract(OLD.payload,'$.matchId')) THEN 1 ELSE 0 END))<>0;
 UPDATE d1_verification_totals SET value=value+(-(CASE WHEN (json_extract(OLD.payload,'$.circuit')='tennis-europe' AND (COALESCE(json_extract(OLD.payload,'$.playerId'),'')='' OR COALESCE(json_extract(OLD.payload,'$.matchId'),'')='' OR COALESCE(json_extract(OLD.payload,'$.date'),'')='' OR COALESCE(json_extract(OLD.payload,'$.tournamentName'),'')='' OR COALESCE(json_extract(OLD.payload,'$.opponent'),'')='' OR COALESCE(json_extract(OLD.payload,'$.round'),'')='' OR (json_extract(OLD.payload,'$.status')='completed' AND COALESCE(json_extract(OLD.payload,'$.result'),'')=''))) THEN 1 ELSE 0 END)) WHERE metric='appInvalid' AND (-(CASE WHEN (json_extract(OLD.payload,'$.circuit')='tennis-europe' AND (COALESCE(json_extract(OLD.payload,'$.playerId'),'')='' OR COALESCE(json_extract(OLD.payload,'$.matchId'),'')='' OR COALESCE(json_extract(OLD.payload,'$.date'),'')='' OR COALESCE(json_extract(OLD.payload,'$.tournamentName'),'')='' OR COALESCE(json_extract(OLD.payload,'$.opponent'),'')='' OR COALESCE(json_extract(OLD.payload,'$.round'),'')='' OR (json_extract(OLD.payload,'$.status')='completed' AND COALESCE(json_extract(OLD.payload,'$.result'),'')=''))) THEN 1 ELSE 0 END))<>0;
 UPDATE d1_verification_totals SET value=value+(-(CASE WHEN (json_extract(OLD.payload,'$.circuit')='tennis-europe' AND COALESCE(json_extract(OLD.payload,'$.court'),'')<>'' AND json_extract(OLD.payload,'$.sourceUrl') LIKE '%/matches/%' AND COALESCE(CAST(json_extract(OLD.payload,'$.courtMatchNumber') AS INTEGER),0)<=0) THEN 1 ELSE 0 END)) WHERE metric='appMissingCourtMatchNumbers' AND (-(CASE WHEN (json_extract(OLD.payload,'$.circuit')='tennis-europe' AND COALESCE(json_extract(OLD.payload,'$.court'),'')<>'' AND json_extract(OLD.payload,'$.sourceUrl') LIKE '%/matches/%' AND COALESCE(CAST(json_extract(OLD.payload,'$.courtMatchNumber') AS INTEGER),0)<=0) THEN 1 ELSE 0 END))<>0;
END;
