json_extract(NEW.payload,'$.matchId') IS NOT NULL) AND (SELECT COUNT(*) FROM (SELECT 1 FROM app_matches WHERE (json_extract(payload,'$.circuit')='tennis-europe' AND json_extract(payload,'$.matchId') IS NOT NULL) AND json_extract(payload,'$.matchId') IS json_extract(NEW.payload,'$.matchId') LIMIT 2))=1 THEN 1 ELSE 0 END) ELSE 0 END)-(CASE WHEN NOT (COALESCE((json_extract(OLD.payload,'$.circuit')='tennis-europe' AND json_extract(OLD.payload,'$.matchId') IS NOT NULL),0) AND COALESCE((json_extract(NEW.payload,'$.circuit')='tennis-europe' AND json_extract(NEW.payload,'$.matchId') IS NOT NULL),0) AND json_extract(OLD.payload,'$.matchId') IS json_extract(NEW.payload,'$.matchId')) THEN (CASE WHEN (json_extract(OLD.payload,'$.circuit')='tennis-europe' AND json_extract(OLD.payload,'$.matchId') IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM app_matches WHERE (json_extract(payload,'$.circuit')='tennis-europe' AND json_extract(payload,'$.matchId') IS NOT NULL) AND json_extract(payload,'$.matchId') IS json_extract(OLD.payload,'$.matchId')) THEN 1 ELSE 0 END) ELSE 0 END))<>0;
