amentName'),'')='' OR COALESCE(json_extract(OLD.payload,'$.opponent'),'')='' OR COALESCE(json_extract(OLD.payload,'$.round'),'')='' OR (json_extract(OLD.payload,'$.status')='completed' AND COALESCE(json_extract(OLD.payload,'$.result'),'')=''))) THEN 1 ELSE 0 END))<>0;
