CREATE TRIGGER IF NOT EXISTS verification_entries_insert AFTER INSERT ON entries BEGIN
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (1) THEN 1 ELSE 0 END) WHERE metric='entries' AND (CASE WHEN (1) THEN 1 ELSE 0 END)<>0;
END;
