CREATE TRIGGER IF NOT EXISTS verification_observed_players_insert AFTER INSERT ON observed_players BEGIN
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (1) THEN 1 ELSE 0 END) WHERE metric='observedPlayers' AND (CASE WHEN (1) THEN 1 ELSE 0 END)<>0;
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (NEW.circuit='fitp') THEN 1 ELSE 0 END) WHERE metric='observedFitp' AND (CASE WHEN (NEW.circuit='fitp') THEN 1 ELSE 0 END)<>0;
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (NEW.circuit='tennis-europe') THEN 1 ELSE 0 END) WHERE metric='observedTe' AND (CASE WHEN (NEW.circuit='tennis-europe') THEN 1 ELSE 0 END)<>0;
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (NEW.circuit='itf') THEN 1 ELSE 0 END) WHERE metric='observedItf' AND (CASE WHEN (NEW.circuit='itf') THEN 1 ELSE 0 END)<>0;
END;
