 UPDATE d1_verification_totals SET value=value+((CASE WHEN (1) THEN 1 ELSE 0 END)-(CASE WHEN (1) THEN 1 ELSE 0 END)) WHERE metric='players' AND ((CASE WHEN (1) THEN 1 ELSE 0 END)-(CASE WHEN (1) THEN 1 ELSE 0 END))<>0;
