CREATE TRIGGER IF NOT EXISTS verification_tournaments_insert AFTER INSERT ON tournaments BEGIN
 UPDATE d1_verification_totals SET value=value+(CASE WHEN (NEW.id LIKE 'te-oop:%') THEN 1 ELSE 0 END) WHERE metric='teOopTournaments' AND (CASE WHEN (NEW.id LIKE 'te-oop:%') THEN 1 ELSE 0 END)<>0;
END;
